def inside_out(x):
    if not isinstance(x, str):
        raise ValueError("Input must be a string")

    result = []
    for word in x.split():
        n = len(word)
        if n % 2 == 0:
            # Even length: move all letters
            half = n // 2
            result.append(word[half:] + word[:half])
        else:
            # Odd length: leave middle letter in place
            half = n // 2
            result.append(word[half+1:] + word[half] + word[:half])

    return ' '.join(result)
